content:
/** @type {import('tailwindcss').Config} */
module.exports = {
  content: [
    "./index.html",
    "./src/**/*.{js,ts,jsx,tsx}",
  ],
  theme: {
    extend: {
      colors: {
        ocean: {
          950: '#060a12', // Deep sea dark black-blue
          900: '#0c1524', // Deep navy
          800: '#152238', // Weathered navy
          700: '#1d3150', // Steel ocean
          500: '#38bdf8', // Sea sky
        },
        gold: {
          DEFAULT: '#d97706', // Old gold / Amber 600
          50: '#fef3c7',
          100: '#fde68a',
          400: '#fbbf24',
          500: '#f59e0b',
          600: '#d97706',
          700: '#b45309',
        }
      },
      fontFamily: {
        serif: ['Georgia', 'ui-serif', 'serif'],
        sans: ['Inter', 'ui-sans-serif', 'system-ui', '-apple-system', 'sans-serif'],
      },
      boxShadow: {
        'gold-glow': '0 0 20px rgba(217, 119, 6, 0.15)',
        'gold-glow-strong': '0 0 35px rgba(217, 119, 6, 0.3)',
      }
    },
  },
  plugins: [],
}

import React, { useState, useEffect } from 'react';
import { Compass, Menu, X, Anchor } from 'lucide-react';

export default function Header() {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 30);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navLinks = [
    { name: 'The Legend', href: '#hero' },
    { name: 'Voyages', href: '#voyages' },
    { name: 'Arsenal', href: '#arsenal' },
    { name: 'Credentials', href: '#credentials' },
    { name: 'Contact', href: '#contact' }
  ];

  return (
    <header className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${
      scrolled 
        ? 'bg-ocean-950/90 backdrop-blur-md border-b border-ocean-800/80 py-4 shadow-lg' 
        : 'bg-transparent py-6'
    }`}>
      <div className="max-w-7xl mx-auto px-6 md:px-12 flex justify-between items-center">

        {/* Premium Brand Logo */}
        <a href="#hero" className="flex items-center gap-3 group">
          <div className="w-10 h-10 rounded-full bg-ocean-900 border border-gold-500/30 flex items-center justify-center group-hover:border-gold-500 transition-all">
            <Compass className="w-5 h-5 text-gold-500 group-hover:rotate-45 transition-transform duration-500" />
          </div>
          <span className="font-cinzel font-bold text-lg tracking-wider text-slate-100 group-hover:text-gold-400 transition-colors">
            CAPTAIN JACK
          </span>
        </a>

        {/* Desktop Navigation */}
        <nav className="hidden md:flex items-center gap-8">
          {navLinks.map((link) => (
            <a
              key={link.name}
              href={link.href}
              className="text-sm font-medium text-slate-300 hover:text-gold-400 tracking-wide transition-colors relative py-1 group"
            >
              {link.name}
              <span className="absolute bottom-0 left-0 w-0 h-[2px] bg-gold transition-all duration-300 group-hover:w-full" />
            </a>
          ))}
          <a
            href="#contact"
            className="px-5 py-2 rounded-full border border-gold text-xs uppercase tracking-wider font-semibold text-gold-400 hover:bg-gold hover:text-ocean-950 transition-all duration-300"
          >
            Parlay
          </a>
        </nav>

        {/* Mobile Menu Button */}
        <button 
          onClick={() => setIsOpen(!isOpen)}
          className="md:hidden p-2 text-slate-300 hover:text-gold-400 transition-colors"
          aria-label="Toggle Navigation Menu"
        >
          {isOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
        </button>
      </div>

      {/* Mobile Drawer */}
      {isOpen && (
        <div className="md:hidden fixed inset-0 top-[73px] bg-ocean-950/98 backdrop-blur-lg border-t border-ocean-900 z-40 px-6 py-8 flex flex-col gap-6">
          {navLinks.map((link) => (
            <a
              key={link.name}
              href={link.href}
              onClick={() => setIsOpen(false)}
              className="text-lg font-cinzel font-semibold text-slate-200 hover:text-gold-400 border-b border-ocean-900 pb-3"
            >
              {link.name}
            </a>
          ))}
          <a
            href="#contact"
            onClick={() => setIsOpen(false)}
            className="w-full text-center py-3 rounded-lg border border-gold text-sm font-semibold text-gold uppercase tracking-widest hover:bg-gold hover:text-ocean-950 transition-all"
          >
            Parlay
          </a>
        </div>
      )}
    </header>
  );
}

import React from 'react';
import { motion } from 'framer-motion';
import { Shield, Sparkles, Terminal, Code } from 'lucide-react';

export default function Skills({ skills }) {
  // Separate original list of skills dynamically based on context:
  // "Privateering", "Bucaneering", "Parler", "Rum" are maritime/pirate skills.
  // "R", "Android", "Linux", "html", "css", "LATEX", "python", "javascript" are digital skills.

  const maritimeSkills = skills.filter(skill => 
    ["Privateering", "Bucaneering", "Parler", "Rum"].includes(skill)
  );

  const digitalSkills = skills.filter(skill => 
    !["Privateering", "Bucaneering", "Parler", "Rum"].includes(skill)
  );

  return (
    <section id="arsenal" className="py-24 relative overflow-hidden">
      <div className="max-w-6xl mx-auto px-6 md:px-12">

        {/* Header */}
        <div className="text-center max-w-2xl mx-auto mb-16">
          <h2 className="text-3xl sm:text-4xl font-bold font-cinzel text-white mb-4 tracking-wider">
            The Captain’s Arsenal
          </h2>
          <div className="w-16 h-1 bg-gold mx-auto mb-4" />
          <p className="text-slate-400">
            A rare combination of legendary buccaneering attributes and deep, technical shipware development.
          </p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">

          {/* Card 1: Buccaneering Attributes */}
          <motion.div 
            initial={{ opacity: 0, x: -30 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.6 }}
            className="p-8 rounded-2xl bg-ocean-900/40 border border-ocean-800 backdrop-blur-sm relative"
          >
            <div className="flex items-center gap-3 mb-6">
              <div className="p-2.5 rounded-lg bg-gold/10 border border-gold/30 text-gold">
                <Shield className="w-6 h-6" />
              </div>
              <div>
                <h3 className="text-xl font-cinzel font-bold text-white">Buccaneer & Negotiator</h3>
                <p className="text-xs text-slate-400">Diplomatic parleys and swordship</p>
              </div>
            </div>

            <p className="text-slate-400 text-sm mb-6 leading-relaxed">
              Forged on high seas, mastering code words and legal technicalities. Parler is more of a guideline than actual rules, aye?
            </p>

            <div className="flex flex-wrap gap-2.5">
              {maritimeSkills.map((skill, index) => (
                <div 
                  key={index} 
                  className="px-4 py-2 rounded-lg bg-ocean-950 border border-gold-600/20 text-gold-100 text-sm font-medium hover:border-gold-500/60 transition-colors cursor-default"
                >
                  {skill}
                </div>
              ))}
            </div>
          </motion.div>

          {/* Card 2: Digital Ocean Stack */}
          <motion.div 
            initial={{ opacity: 0, x: 30 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.6 }}
            className="p-8 rounded-2xl bg-ocean-900/40 border border-ocean-800 backdrop-blur-sm relative"
          >
            <div className="flex items-center gap-3 mb-6">
              <div className="p-2.5 rounded-lg bg-sky-500/10 border border-sky-500/30 text-sky-400">
                <Code className="w-6 h-6" />
              </div>
              <div>
                <h3 className="text-xl font-cinzel font-bold text-white">Digital Seas Navigations</h3>
                <p className="text-xs text-slate-400">Deep stack scripting and document crafting</p>
              </div>
            </div>

            <p className="text-slate-400 text-sm mb-6 leading-relaxed">
              When not commanding wooden hulls, orchestrating Linux kernel operations and building scalable architectures to calculate course navigations.
            </p>

            <div className="flex flex-wrap gap-2.5">
              {digitalSkills.map((skill, index) => (
                <div 
                  key={index} 
                  className="px-4 py-2 rounded-lg bg-ocean-950 border border-sky-500/15 text-slate-100 text-sm font-medium hover:border-sky-500/50 transition-colors cursor-default"
                >
                  {skill}
                </div>
              ))}
            </div>
          </motion.div>

        </div>

      </div>
    </section>
  );
}

import React from 'react';
import { motion } from 'framer-motion';
import { Anchor, Terminal, Skull, Compass } from 'lucide-react';

export default function Hero({ data }) {
  return (
    <section id="hero" className="relative min-h-screen flex items-center justify-center pt-24 pb-16 px-6 overflow-hidden">

      {/* Decorative Star/Grid Overlay */}
      <div className="absolute inset-0 bg-[radial-gradient(#1e293b_1px,transparent_1px)] [background-size:24px_24px] opacity-20 pointer-events-none" />

      <div className="max-w-7xl mx-auto w-full grid grid-cols-1 lg:grid-cols-12 gap-12 items-center relative z-10">

        {/* Left Side: Editorial Introduction */}
        <div className="lg:col-span-7 flex flex-col justify-center space-y-6 text-left order-2 lg:order-1">

          <motion.div 
            initial={{ opacity: 0, y: 15 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6 }}
            className="inline-flex items-center gap-2 px-3.5 py-1.5 rounded-full bg-gold-900/20 border border-gold-600/40 text-gold-400 text-xs font-semibold tracking-widest uppercase w-fit"
          >
            <Compass className="w-3.5 h-3.5 animate-spin" style={{ animationDuration: '10s' }} />
            Not all treasure is silver and gold, mate.
          </motion.div>

          <motion.h1 
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.7, delay: 0.1 }}
            className="text-4xl sm:text-6xl lg:text-7xl font-bold tracking-tight text-white font-cinzel leading-none"
          >
            Captain <br />
            <span className="text-transparent bg-clip-text bg-gradient-to-r from-gold-400 via-amber-500 to-gold-600 drop-shadow-sm">
              {data.name}
            </span>
          </motion.h1>

          <motion.p 
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.7, delay: 0.2 }}
            className="text-slate-300 text-base sm:text-lg max-w-xl leading-relaxed"
          >
            Unmatched master of the Black Pearl, voyager of both physical and digital oceans. Balancing maritime lawless glory and high-tech scriptcrafting from the Caribbean seas to London.
          </motion.p>

          {/* Quick info widgets */}
          <motion.div 
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.7, delay: 0.3 }}
            className="grid grid-cols-2 gap-4 max-w-md pt-2"
          >
            <div className="p-4 rounded-xl bg-ocean-900/60 border border-ocean-800 backdrop-blur-sm">
              <span className="block text-xs uppercase text-slate-500 font-semibold tracking-wider">Commanding</span>
              <span className="text-slate-200 font-cinzel font-bold text-lg">The Black Pearl</span>
            </div>
            <div className="p-4 rounded-xl bg-ocean-900/60 border border-ocean-800 backdrop-blur-sm">
              <span className="block text-xs uppercase text-slate-500 font-semibold tracking-wider">Primary Fleet</span>
              <span className="text-slate-200 font-cinzel font-bold text-lg">Rum & Terminal</span>
            </div>
          </motion.div>

          {/* Call to Action buttons */}
          <motion.div 
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.7, delay: 0.4 }}
            className="flex flex-wrap gap-4 pt-4"
          >
            <a 
              href="#voyages" 
              className="px-6 py-3.5 rounded-lg bg-gradient-to-r from-gold-600 to-gold-700 text-slate-950 font-bold hover:shadow-gold-glow-strong text-sm uppercase tracking-wider flex items-center gap-2 transition-all"
            >
              <Anchor className="w-4 h-4" />
              View Voyages
            </a>
            <a 
              href="#contact" 
              className="px-6 py-3.5 rounded-lg border border-slate-700 bg-ocean-950/40 backdrop-blur-sm text-slate-300 hover:text-gold hover:border-gold/50 text-sm uppercase tracking-wider flex items-center gap-2 transition-all"
            >
              <Terminal className="w-4 h-4" />
              Negotiate terms
            </a>
          </motion.div>
        </div>

        {/* Right Side: Portrait Image Frame */}
        <div className="lg:col-span-5 flex justify-center order-1 lg:order-2">
          <motion.div 
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ duration: 0.8 }}
            className="relative w-72 h-72 sm:w-80 sm:h-80 md:w-96 md:h-96"
          >
            {/* Outer golden circular compass rings */}
            <div className="absolute inset-[-10px] rounded-full border border-dashed border-gold-600/30 animate-spin" style={{ animationDuration: '40s' }} />
            <div className="absolute inset-[-20px] rounded-full border border-gold-600/10 animate-spin" style={{ animationDuration: '80s', animationDirection: 'reverse' }} />

            {/* Main Portrait Frame */}
            <div className="absolute inset-0 rounded-2xl overflow-hidden border-2 border-gold-500/30 bg-ocean-900 shadow-gold-glow group">
              <img 
                src="https://placehold.co/500x500/152238/fbbf24?text=Captain+Jack+Sparrow" 
                alt="Captain Jack Sparrow Portrait"
                data-img-slot="hero-avatar" 
                data-img-label="Captain Jack Sparrow Portrait"
                className="w-full h-full object-cover filter contrast-125 brightness-95 grayscale-[15%] transition-all duration-500 group-hover:scale-105"
              />
              {/* Soft overlay vignette */}
              <div className="absolute inset-0 bg-gradient-to-t from-ocean-950 via-transparent to-transparent opacity-80" />

              {/* Small pirate badge tag overlay */}
              <div className="absolute bottom-4 left-4 right-4 bg-ocean-950/90 backdrop-blur-sm border border-gold-600/30 rounded-lg p-3 text-center">
                <div className="flex items-center justify-center gap-2 text-xs uppercase font-bold text-gold-400">
                  <Skull className="w-4 h-4 text-gold-500" />
                  Wanted Dead or Alive
                </div>
              </div>
            </div>
          </motion.div>
        </div>

      </div>
    </section>
  );
}

import React from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import Experience from './components/Experience';
import Skills from './components/Skills';
import Education from './components/Education';
import Contact from './components/Contact';
import Footer from './components/Footer';

// Safe parsed mock data exactly from the input JSON
const portfolioData = {
  name: "Jack Sparrow",
  email: "jack@sparrow.org",
  phone_number: "0099/333 5647380",
  experience: [
    {
      companyname: "Black Pearl",
      role: "Captain",
      period: "2018–2021",
      description: "Finally got the goddamn ship back. Lorem ipsum dolor sit amet, consectetur adipiscing elit. Donec a diam lectus."
    },
    {
      companyname: "Black Pearl",
      role: "Captain",
      period: "2016–2017",
      description: "Found a secret treasure, lost the ship. Lorem ipsum dolor sit amet, consectetur adipiscing elit. Donec a diam lectus."
    },
    {
      companyname: "Freelance",
      role: "Pirate",
      period: "2019",
      description: "This and that. The usual, aye? Lorem ipsum dolor sit amet, consectetur adipiscing elit. Donec a diam lectus."
    }
  ],
  skills: [
    "Privateering",
    "Bucaneering",
    "Parler",
    "Rum",
    "R",
    "Android",
    "Linux",
    "html",
    "css",
    "LATEX",
    "python",
    "javascript"
  ],
  education: [
    {
      institution: "Tortuga Uni",
      period: "1710",
      degree: "Captain",
      grade: "N/A",
      location: "Tortuga"
    },
    {
      institution: "London",
      period: "1715",
      degree: "M.A. in Bucaneering",
      grade: "N/A",
      location: "London"
    },
    {
      institution: "London",
      period: "1720",
      degree: "B.A. in Bucaneering",
      grade: "N/A",
      location: "London"
    }
  ],
  certification: [
    {
      name: "Captain’s Certificates",
      period: "1708"
    },
    {
      name: "Travel grant",
      period: "1710"
    },
    {
      name: "Grant from the Pirate’s Company",
      period: "1715–1716"
    }
  ]
};

export default function App() {
  // Notice: 'project' is an empty array in source JSON, hence the project section is completely omitted from render.
  return (
    <div className="min-h-screen bg-ocean-950 text-slate-200 selection:bg-gold-600/30 selection:text-gold-100 overflow-x-hidden font-sans relative">

      {/* Decorative subtle deep ocean glow background */}
      <div className="absolute top-0 left-0 right-0 h-[600px] bg-gradient-to-b from-gold-900/10 to-transparent pointer-events-none z-0" />
      <div className="absolute top-[30%] right-[-10%] w-[500px] h-[500px] bg-sky-950/20 blur-[120px] rounded-full pointer-events-none" />
      <div className="absolute bottom-[20%] left-[-10%] w-[500px] h-[500px] bg-gold-950/10 blur-[150px] rounded-full pointer-events-none" />

      {/* Main Structural Layout */}
      <Header />
      <main className="relative z-10">
        <Hero data={portfolioData} />

        {/* Experience / Voyages Section */}
        {portfolioData.experience && portfolioData.experience.length > 0 && (
          <Experience voyages={portfolioData.experience} />
        )}

        {/* Skills / Arsenal Section */}
        {portfolioData.skills && portfolioData.skills.length > 0 && (
          <Skills skills={portfolioData.skills} />
        )}

        {/* Education & Credentials Section */}
        {((portfolioData.education && portfolioData.education.length > 0) || 
          (portfolioData.certification && portfolioData.certification.length > 0)) && (
          <Education 
            education={portfolioData.education} 
            certifications={portfolioData.certification} 
          />
        )}

        {/* Contact Section */}
        <Contact contactInfo={{ email: portfolioData.email, phone: portfolioData.phone_number }} />
      </main>

      <Footer name={portfolioData.name} />
    </div>
  );
}

import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
  server: {
    port: 3000,
    host: true
  }
});

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App.jsx';
import './index.css';

ReactDOM.createRoot(document.getElementById('root')).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>,
);

import React from 'react';
import { motion } from 'framer-motion';
import { GraduationCap, Award, MapPin } from 'lucide-react';

export default function Education({ education, certifications }) {
  return (
    <section id="credentials" className="py-24 bg-ocean-900/20 relative">
      <div className="max-w-6xl mx-auto px-6 md:px-12">

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">

          {/* Left Block: Academic Formations */}
          <div className="lg:col-span-7 space-y-8">
            <div>
              <h2 className="text-3xl font-cinzel font-bold text-white tracking-wider">
                Education
              </h2>
              <div className="w-12 h-1 bg-gold mt-3 mb-6" />
              <p className="text-slate-400 text-sm max-w-md">
                Formal naval masterships and high intellectual degrees obtained directly at sea or from London.
              </p>
            </div>

            <div className="space-y-6">
              {education.map((edu, idx) => (
                <motion.div 
                  key={idx}
                  initial={{ opacity: 0, y: 15 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true }}
                  transition={{ duration: 0.4, delay: idx * 0.1 }}
                  className="p-5 rounded-xl bg-ocean-950/70 border border-ocean-800/80 hover:border-gold-500/20 transition-all flex gap-4"
                >
                  <div className="p-2 rounded-lg bg-gold-950/40 border border-gold-600/30 text-gold h-fit">
                    <GraduationCap className="w-5 h-5" />
                  </div>
                  <div className="flex-1 space-y-1">
                    <div className="flex justify-between items-start flex-wrap gap-2">
                      <h3 className="font-bold text-slate-100">{edu.degree}</h3>
                      <span className="text-xs font-semibold text-gold-400 bg-gold-950/30 px-2.5 py-0.5 rounded border border-gold-500/10">
                        {edu.period}
                      </span>
                    </div>
                    <p className="text-sm text-slate-300 font-medium">{edu.institution}</p>

                    {edu.location && edu.location !== "N/A" && (
                      <div className="flex items-center gap-1 text-xs text-slate-500 pt-1">
                        <MapPin className="w-3.5 h-3.5" />
                        {edu.location}
                      </div>
                    )}
                  </div>
                </motion.div>
              ))}
            </div>
          </div>

          {/* Right Block: Grants & Certificates */}
          <div className="lg:col-span-5 space-y-8">
            <div>
              <h2 className="text-3xl font-cinzel font-bold text-white tracking-wider">
                Endorsements
              </h2>
              <div className="w-12 h-1 bg-gold mt-3 mb-6" />
              <p className="text-slate-400 text-sm max-w-sm">
                Sanctioned certifications and travel warrants legally approved by standard maritime commissions.
              </p>
            </div>

            <div className="space-y-4">
              {certifications.map((cert, idx) => (
                <motion.div 
                  key={idx}
                  initial={{ opacity: 0, y: 15 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true }}
                  transition={{ duration: 0.4, delay: idx * 0.1 }}
                  className="p-4 rounded-xl bg-ocean-950/50 border border-ocean-900 flex items-center justify-between gap-4"
                >
                  <div className="flex items-center gap-3">
                    <div className="w-9 h-9 rounded-full bg-gold-600/10 flex items-center justify-center text-gold border border-gold-500/20">
                      <Award className="w-4.5 h-4.5" />
                    </div>
                    <span className="text-slate-200 text-sm font-medium leading-tight">
                      {cert.name}
                    </span>
                  </div>
                  <span className="text-xs font-mono text-slate-500 whitespace-nowrap">
                    {cert.period}
                  </span>
                </motion.div>
              ))}
            </div>
          </div>

        </div>

      </div>
    </section>
  );
}

@tailwind base;
@tailwind components;
@tailwind utilities;

/* Custom Scrollbar */
::-webkit-scrollbar {
  width: 8px;
}
::-webkit-scrollbar-track {
  background: #060a12;
}
::-webkit-scrollbar-thumb {
  background: #152238;
  border-radius: 4px;
}
::-webkit-scrollbar-thumb:hover {
  background: #d97706;
}

/* Custom interactive classes */
.glow-border {
  border: 1px solid rgba(217, 119, 6, 0.2);
  transition: all 0.3s ease;
}
.glow-border:hover {
  border-color: rgba(217, 119, 6, 0.6);
  box-shadow: 0 0 15px rgba(217, 119, 6, 0.1);
}

import React from 'react';
import { motion } from 'framer-motion';
import { Compass, Ship, Calendar, Award } from 'lucide-react';

export default function Experience({ voyages }) {
  // Sorting voyages or mapping safely
  return (
    <section id="voyages" className="py-24 bg-ocean-900/30 border-y border-ocean-900/50 relative">
      <div className="max-w-6xl mx-auto px-6 md:px-12">

        {/* Section Header */}
        <div className="text-center max-w-2xl mx-auto mb-16">
          <h2 className="text-3xl sm:text-4xl font-bold font-cinzel text-white mb-4 tracking-wider">
            Chronicles of the Sea
          </h2>
          <div className="w-16 h-1 bg-gold mx-auto mb-4" />
          <p className="text-slate-400">
            A history of hard-fought voyages, stolen ships, legendary plunderings, and unexpected returns to power.
          </p>
        </div>

        {/* Timeline representation */}
        <div className="relative max-w-3xl mx-auto">
          {/* Vertical Timeline Center Line */}
          <div className="absolute left-4 md:left-1/2 top-0 bottom-0 w-[2px] bg-gradient-to-b from-gold-600/50 via-ocean-800 to-transparent" />

          <div className="space-y-12">
            {voyages.map((voyage, idx) => {
              const isEven = idx % 2 === 0;
              return (
                <motion.div 
                  key={idx}
                  initial={{ opacity: 0, y: 30 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true, margin: '-100px' }}
                  transition={{ duration: 0.6 }}
                  className={`flex flex-col md:flex-row relative items-start ${
                    isEven ? 'md:flex-row-reverse' : ''
                  }`}
                >

                  {/* Outer center dot */}
                  <div className="absolute left-4 md:left-1/2 w-8 h-8 rounded-full bg-ocean-950 border-2 border-gold-500 flex items-center justify-center transform -translate-x-1/2 z-10 shadow-gold-glow">
                    <Ship className="w-3.5 h-3.5 text-gold" />
                  </div>

                  {/* Empty space filler for desktop spacing */}
                  <div className="hidden md:block w-1/2" />

                  {/* Card Content Box */}
                  <div className="w-full md:w-1/2 pl-12 md:pl-0 md:px-8">
                    <div className="p-6 rounded-xl bg-ocean-950/80 border border-ocean-800 hover:border-gold-500/40 transition-all duration-300 shadow-lg relative group">

                      {/* Decorative subtle gold hover flag */}
                      <div className="absolute top-0 right-0 w-24 h-24 bg-gradient-to-bl from-gold-500/5 to-transparent pointer-events-none rounded-tr-xl" />

                      {/* Period Flag */}
                      <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-gold-950/30 border border-gold-600/20 text-gold-400 text-xs font-semibold mb-4">
                        <Calendar className="w-3.5 h-3.5" />
                        {voyage.period}
                      </span>

                      <h3 className="text-xl font-cinzel font-bold text-white group-hover:text-gold transition-colors">
                        {voyage.role}
                      </h3>

                      <div className="text-sm text-gold-400/90 font-semibold mb-3 flex items-center gap-2">
                        <span>{voyage.companyname}</span>
                      </div>

                      <p className="text-slate-400 text-sm leading-relaxed">
                        {voyage.description}
                      </p>

                    </div>
                  </div>

                </motion.div>
              );
            })}
          </div>
        </div>

      </div>
    </section>
  );
}

