        {/* Brand identity */}
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 rounded-full bg-ocean-900 border border-gold/30 flex items-center justify-center">
            <Compass className="w-4 h-4 text-gold" />
          </div>
          <span className="font-cinzel font-bold text-slate-300 tracking-wider text-sm">
